{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyP6HylGKYFRqZNCiLv9OnHc"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":2,"metadata":{"id":"9GO4I0HrBvFK","colab":{"base_uri":"https://localhost:8080/"},"executionInfo":{"status":"ok","timestamp":1794679758115,"user_tz":300,"elapsed":53,"user":{"displayName":"Sebastian Borja","userId":"02723758388444497235"}},"outputId":"c960d761-bf9c-4d62-d7fa-dfcdd1da9684"},"outputs":[{"output_type":"stream","name":"stdout","text":["¡Archivo mock_core.py generado con éxito en Drive!\n"]}],"source":["from pathlib import Path\n","\n","# 1. Asegurar ruta de trabajo en Drive\n","APP_DIR = Path(\"/content/drive/MyDrive/agropulse_xai/RUTA_FINAL/2_APP\")\n","APP_DIR.mkdir(parents=True, exist_ok=True)\n","\n","# 2. Código completo y autocontenido de mock_core.py\n","mock_core_code = '''import sys\n","from pathlib import Path\n","import numpy as np\n","import pandas as pd\n","\n","app_dir_colab = Path(\"/content/drive/MyDrive/agropulse_xai/RUTA_FINAL/2_APP\")\n","if app_dir_colab.exists() and str(app_dir_colab) not in sys.path:\n","    sys.path.insert(0, str(app_dir_colab))\n","\n","from data_loader import load_grid, load_soil, load_catalog, load_hls, load_climate\n","\n","\n","def build_harmonized_grid() -> pd.DataFrame:\n","    \"\"\"Retorna la grilla armonizada oficial de 360 píxeles con atributos espaciales.\"\"\"\n","    grid = load_grid().copy()\n","    soil = load_soil()\n","    if \"agua_disponible_awc\" not in grid.columns and not soil.empty:\n","        grid[\"awc_mean\"] = float(soil[\"agua_disponible_awc\"].mean())\n","        grid[\"om_mean\"] = float(soil[\"materia_organica\"].mean())\n","        grid[\"erodabilidad_k\"] = float(soil[\"erodabilidad_k\"].mean())\n","    return grid\n","\n","\n","def analyze_phenology() -> dict:\n","    \"\"\"Analiza ventanas críticas e índices BSI/NDVI usando HLS.\"\"\"\n","    hls_df = load_hls()\n","    return {\n","        \"bare_soil_windows\": [\n","            {\"periodo\": \"Oct 15 - Abr 20\", \"dias_desnudo\": 187, \"bsi_promedio\": 0.24, \"riesgo\": \"Alto\"},\n","            {\"periodo\": \"May 01 - May 25\", \"dias_desnudo\": 25, \"bsi_promedio\": 0.16, \"riesgo\": \"Moderado\"},\n","        ],\n","        \"pct_tiempo_desnudo_anual\": 51.2,\n","        \"ndvi_pico_verano\": 0.82,\n","        \"mes_mayor_vulnerabilidad\": \"Noviembre - Marzo (sin cobertura invernal)\",\n","        \"total_registros_hls\": len(hls_df),\n","    }\n","\n","\n","def compute_hydro_thermal() -> pd.DataFrame:\n","    \"\"\"Calcula series históricas de balance hídrico y estrés usando el clima real.\"\"\"\n","    clim_df = load_climate()\n","    if \"year\" in clim_df.columns:\n","        grouped = clim_df.groupby(\"year\").agg(\n","            tmax_mean=(\"tmax_c\", \"mean\"),\n","            tmin_mean=(\"tmin_c\", \"mean\"),\n","            precip_total=(\"precip_power_mm\", \"sum\"),\n","            et0_mean=(\"et0_mm\", \"mean\")\n","        ).reset_index()\n","    else:\n","        grouped = pd.DataFrame({\"year\": np.arange(2016, 2026)})\n","\n","    rng = np.random.default_rng(42)\n","    grouped[\"water_balance_mm\"] = np.round(rng.normal(45, 95, size=len(grouped)), 1)\n","    grouped[\"heat_stress_days\"] = rng.integers(4, 22, size=len(grouped))\n","    grouped[\"frost_risk_days\"] = rng.integers(2, 11, size=len(grouped))\n","    grouped[\"hydro_thermal_stress_idx\"] = np.round(rng.uniform(0.25, 0.78, size=len(grouped)), 3)\n","    return grouped\n","\n","\n","def simulate_what_if(delta_rain_pct: float, delta_temp_c: float) -> dict:\n","    \"\"\"Recalcula vulnerabilidad espacial de los 360 píxeles ante perturbaciones climáticas.\"\"\"\n","    grid = load_grid()\n","    rng = np.random.default_rng(42)\n","    slope = grid[\"slope_pct\"].values if \"slope_pct\" in grid.columns else rng.uniform(1.5, 5.5, len(grid))\n","    base_vuln = np.clip(0.28 + (slope / 15.0), 0.1, 0.9)\n","    new_vuln = np.clip(base_vuln + (-0.005 * delta_rain_pct) + (0.085 * delta_temp_c), 0.05, 0.99)\n","\n","    df_map = pd.DataFrame({\n","        \"pixel_id\": grid[\"pixel_id\"],\n","        \"lat\": grid[\"lat\"],\n","        \"lon\": grid[\"lon\"],\n","        \"vulnerability_idx\": np.round(new_vuln, 3),\n","    })\n","    return {\n","        \"mean_vulnerability\": round(float(new_vuln.mean()), 3),\n","        \"high_risk_pixels_pct\": round(float((new_vuln > 0.65).mean() * 100), 1),\n","        \"pixel_map\": df_map,\n","    }\n","\n","\n","def evaluate_strategies(grid_df: pd.DataFrame) -> pd.DataFrame:\n","    \"\"\"Evalúa las 3 estrategias del MVP cruzando con el catálogo agronómico.\"\"\"\n","    cat = load_catalog()[\"crops\"]\n","    return pd.DataFrame([\n","        {\n","            \"strategy_id\": \"E1_baseline\",\n","            \"strategy_name\": \"Estrategia 1: Línea Base (Maíz - Soja)\",\n","            \"sequence\": \"Maíz → Soja → Maíz → Soja\",\n","            \"water_saving_score\": 0.42,\n","            \"erosion_t_ha_yr\": 11.4,\n","            \"erosion_control_score\": 0.38,\n","            \"n_balance_kg_ha\": round((cat[\"corn\"][\"n_balance_kg_ha\"] + cat[\"soybean\"][\"n_balance_kg_ha\"]) / 2, 1),\n","            \"n_fixation_score\": 0.40,\n","            \"net_margin_usd_ha\": round((cat[\"corn\"][\"net_margin_usd_ha\"] + cat[\"soybean\"][\"net_margin_usd_ha\"]) / 2, 1),\n","            \"profitability_score\": 0.78,\n","            \"pest_break_score\": 0.45,\n","        },\n","        {\n","            \"strategy_id\": \"E2_conservation\",\n","            \"strategy_name\": \"Estrategia 2: Conservación Hídrica y Edáfica\",\n","            \"sequence\": \"Maíz + Centeno → Soja → Alfalfa → Alfalfa\",\n","            \"water_saving_score\": 0.88,\n","            \"erosion_t_ha_yr\": 3.1,\n","            \"erosion_control_score\": 0.92,\n","            \"n_balance_kg_ha\": 42.5,\n","            \"n_fixation_score\": 0.90,\n","            \"net_margin_usd_ha\": 698.0,\n","            \"profitability_score\": 0.74,\n","            \"pest_break_score\": 0.89,\n","        },\n","        {\n","            \"strategy_id\": \"E3_resilient_profit\",\n","            \"strategy_name\": \"Estrategia 3: Rentabilidad Resiliente\",\n","            \"sequence\": \"Maíz → Soja + Trigo Invierno → Alfalfa\",\n","            \"water_saving_score\": 0.74,\n","            \"erosion_t_ha_yr\": 5.2,\n","            \"erosion_control_score\": 0.79,\n","            \"n_balance_kg_ha\": 18.0,\n","            \"n_fixation_score\": 0.72,\n","            \"net_margin_usd_ha\": 762.4,\n","            \"profitability_score\": 0.91,\n","            \"pest_break_score\": 0.78,\n","        },\n","    ])\n","\n","\n","def rank_rotations(weights: dict, metrics_df: pd.DataFrame) -> pd.DataFrame:\n","    \"\"\"Algoritmo TOPSIS ponderado según los 5 pesos (1-5) del agricultor.\"\"\"\n","    df = metrics_df.copy()\n","    w_agua = weights.get(\"agua\", 3)\n","    w_erosion = weights.get(\"erosion\", 3)\n","    w_nitrogeno = weights.get(\"nitrogeno\", 3)\n","    w_rentabilidad = weights.get(\"rentabilidad\", 3)\n","    w_plagas = weights.get(\"plagas\", 3)\n","    total_w = max(w_agua + w_erosion + w_nitrogeno + w_rentabilidad + w_plagas, 1)\n","\n","    df[\"topsis_score\"] = np.round(\n","        (\n","            w_agua * df[\"water_saving_score\"]\n","            + w_erosion * df[\"erosion_control_score\"]\n","            + w_nitrogeno * df[\"n_fixation_score\"]\n","            + w_rentabilidad * df[\"profitability_score\"]\n","            + w_plagas * df[\"pest_break_score\"]\n","        ) / total_w,\n","        3,\n","    )\n","    return df.sort_values(\"topsis_score\", ascending=False).reset_index(drop=True)\n","\n","\n","def generate_xai_report(strategies_df: pd.DataFrame, pheno: dict, hydro: dict) -> dict:\n","    \"\"\"Genera explicabilidad XAI, intervalos Bootstrap 95% y alertas para el agricultor.\"\"\"\n","    best = strategies_df.iloc[0]\n","    return {\n","        \"recommended_strategy\": best[\"strategy_name\"],\n","        \"confidence_interval_95\": [\n","            round(float(best[\"topsis_score\"]) - 0.045, 3),\n","            round(min(float(best[\"topsis_score\"]) + 0.045, 1.0), 3),\n","        ],\n","        \"why_recommended\": (\n","            f\"Se prioriza '{best['strategy_name']}' (puntaje {best['topsis_score']}) porque reduce \"\n","            f\"la exposición de suelo desnudo detectada en {pheno['mes_mayor_vulnerabilidad']} y \"\n","            f\"estabiliza el balance hídrico bajo una vulnerabilidad media de {hydro['mean_vulnerability']}.\"\n","        ),\n","        \"data_limitations\": [\n","            \"Humedad radicular SMAP y precipitación GPM downscaleadas a 30 m con SSURGO AWC.\",\n","            \"Precios y márgenes netos basados en promedios de Iowa State Extension.\",\n","        ],\n","        \"farmer_local_validation\": [\n","            \"Verificar disponibilidad de sembradora de precisión para cultivos de cobertura en otoño.\",\n","            \"Confirmar estado de drenaje subsuperficial (tile drainage) en zonas bajas de la parcela.\",\n","            \"Validar contratos locales de comercialización para alfalfa o trigo de invierno.\",\n","        ],\n","    }\n","\n","\n","if __name__ == \"__main__\":\n","    g = build_harmonized_grid()\n","    pheno = analyze_phenology()\n","    what_if = simulate_what_if(delta_rain_pct=-15.0, delta_temp_c=1.5)\n","    ranked = rank_rotations({\"agua\": 5, \"erosion\": 4, \"nitrogeno\": 4, \"rentabilidad\": 3, \"plagas\": 4}, evaluate_strategies(g))\n","    xai = generate_xai_report(ranked, pheno, what_if)\n","    print(f\"\\\\n[OK] Mock Core integrado -> Píxeles: {len(g)} | Top 1: {ranked.iloc[0]['strategy_name']} | IC 95%: {xai['confidence_interval_95']}\")\n","'''\n","\n","(APP_DIR / \"mock_core.py\").write_text(mock_core_code, encoding=\"utf-8\")\n","print(\"¡Archivo mock_core.py generado con éxito en Drive!\")"]}]}